// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, sGuard} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Log logger;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    // fuzz the caller address and the value sent; these are the deciding values
    function testFuzz_property(address caller, uint256 value) public {
        // keep value in a reasonable range so we can fund the caller
        uint256 amt = bound(value, 0, 10 ether);
        // The PUBLIC surface requires a deployed Log with code; replace the initially-deployed Log
        // with our own recording logger so we can observe calls. Deploy logger and set c.LogFile
        // by calling fallback on c (constructor set it but to a different Log instance). The reference
        // requires that Put calls Log.AddMessage, so we deploy a fresh logger and ensure c will call it.
        logger = new Log();
        // Re-deploy c pointing at our logger so that subsequent Put calls target it.
        c = new MY_BANK(address(logger));

        // fund the caller
        vm.deal(caller, amt);
        vm.assume(caller != address(0));

        // record history length before
        uint256 before = logger.HistoryLength();

        bool ok;
        // perform Put from caller with value amt; capture whether it reverts
        vm.prank(caller);
        try c.Put{value: amt}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Put on the reference contract, Log.AddMessage must have been called exactly once more
        // (we assert that when the call succeeded, the logger's history length increased).
        uint256 after_ = logger.HistoryLength();

        // Single assertion: reference always satisfies that successful Put increments logger history;
        // mutant that removed the call will have a successful Put but history did NOT increase for some inputs,
        // causing this assertion to fail.
        assertTrue(!ok || after_ == before + 1);
    }
}

// Minimal recording Log that matches the original contract's AddMessage signature and exposes a getter
contract Log is sGuard {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    // helper getter to observe length (convenience for the test)
    function HistoryLength() external view returns (uint256) {
        return History.length;
    }
}
